
import csv
import re
from pathlib import Path

import streamlit as st

BASE_DIR = Path(__file__).resolve().parents[2]

PROCESSED_DIR = BASE_DIR / "data" / "output"
REJECTED_DIR = BASE_DIR / "data" / "quarantine"

st.set_page_config(
    page_title="Download Results | SmartData",
    page_icon="📥",
    layout="wide"
)

st.title("📥 Download Results")
st.write(
    "Access and download processed transactions and rejected records "
    "generated by your pipeline executions."
)

st.divider()


def get_available_files(directory, pattern):
    directory.mkdir(parents=True, exist_ok=True)

    files = list(directory.glob(pattern))
    return sorted(files, key=lambda file: file.stat().st_mtime, reverse=True)


def extract_run_id(file_path):
    match = re.search(
        r"(?:processed|rejected)_(.+)\.csv$",
        file_path.name
    )
    return match.group(1) if match else "Unknown"


def preview_csv(file_path):
    rows = []

    with open(file_path, "r", encoding="utf-8-sig", newline="") as csv_file:
        reader = csv.DictReader(csv_file)

        for row in reader:
            rows.append(row)

            if len(rows) == 5:
                break

    return rows


def show_download_section(title, files, file_type):
    st.subheader(title)

    if not files:
        st.info(f"No {file_type.lower()} files are available yet.")
        return

    file_options = {
        f"{extract_run_id(file)} | {file.name}": file
        for file in files
    }

    selected_label = st.selectbox(
        f"Select {file_type.lower()} file",
        options=list(file_options.keys()),
        key=f"{file_type}_file_selector"
    )

    selected_file = file_options[selected_label]

    file_size_mb = selected_file.stat().st_size / (1024 * 1024)

    col1, col2 = st.columns(2)

    with col1:
        st.metric("File Size", f"{file_size_mb:.2f} MB")

    with col2:
        st.metric("Preview Records", "First 5 rows")

    st.caption(f"File: {selected_file.name}")
    st.caption(f"Pipeline Run ID: {extract_run_id(selected_file)}")

    st.markdown("#### Data Preview")

    preview_rows = preview_csv(selected_file)

    if preview_rows:
        st.dataframe(
            preview_rows,
            use_container_width=True,
            hide_index=True
        )
    else:
        st.warning("The selected CSV file is empty.")

    with open(selected_file, "rb") as file:
        file_bytes = file.read()

    st.download_button(
        label=f"⬇️ Download {file_type} CSV",
        data=file_bytes,
        file_name=selected_file.name,
        mime="text/csv",
        use_container_width=True,
        key=f"download_{file_type}"
    )


processed_files = get_available_files(
    PROCESSED_DIR,
    "processed_*.csv"
)

rejected_files = get_available_files(
    REJECTED_DIR,
    "rejected_*.csv"
)

col1, col2 = st.columns(2)

with col1:
    st.metric("Processed Files Available", len(processed_files))

with col2:
    st.metric("Rejected Files Available", len(rejected_files))

st.divider()

show_download_section(
    "✅ Processed Transactions",
    processed_files,
    "Processed"
)

st.divider()

show_download_section(
    "⚠️ Rejected Records",
    rejected_files,
    "Rejected"
)

st.divider()

st.caption(
    "SmartData Platform | Download Center | CSV Export"
)
